if mibBuilder.loadTexts: ciscoVoiceDialControlMIB.setDescription('This MIB module enhances the IETF Dial Control MIB\n        (RFC2128) by providing management of voice telephony\n        peers on both a circuit-switched telephony network,\n        and an IP data network.\n\n        *** ABBREVIATIONS, ACRONYMS AND SYMBOLS ***\n\n        GSM    - Global System for Mobile Communication\n\n        AMR-NB - Adaptive Multi Rate - Narrow Band \n\n        iLBC   - internet Low Bitrate Codec \n\n        KPML   - Key Press Markup Language\n\n        MGCP   - Media Gateway Control Protocol.\n\n        SIP    - Session Initiation Protocol.\n\n        H323   - One of the voip signalling protocol.\n\n        SCCP   - Skinny Client Control Protocol.\n\n        dialpeer - This represents a configured interface that \n                   carries the dial map.  A dialpeer maps the \n                   called and calling numbers with the port or \n                   IP interface to be used.\n\n        License call capacity - This represents the licensed \n                                maximum call capacity of \n                                the gateway.\n\n        iSAC    -  Internet Speech Audio Codec\n\n        RPH    - Resource Priority Header\n\n        DSCP   - Diffserv Code Points')
class CvCallVolumeWMIntvlType(TextualConvention, Integer32):
    description = 'Represents the Id of the watermark table.\n        Here is what different values represent\n\n        1 : Seconds Table: Here the entries are among last 60 second\n        2 : Minutes Table: Here the entries are among last 60 minutes\n        3 : Hours Table: Here the entries are among last 72 Hours\n        4 : Uptime Table: Here the entries are from last reload/reboot'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4))
    namedValues = NamedValues(("secondStats", 1), ("minuteStats", 2), ("hourStats", 3), ("fromReloadStats", 4))

class CvCallVolumeStatsIntvlType(TextualConvention, Integer32):
    description = 'Represents the ids of the stats vlolume table\n        Here is what each entry corresponds.\n        1 : Seconds Table: Here each entry corresponds to a second\n        2 : Minutes Table: Here each entry corresponds to a minute\n        3 : Hours Table: Here each entry corresponds to an hour'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3))
    namedValues = NamedValues(("secondStats", 1), ("minuteStats", 2), ("hourStats", 3))

class CvSessionProtocol(TextualConvention, Integer32):
    description = 'Represents a Session Protocol used by Voice calls between a\n        local and remote router via the IP backbone.\n\n        other - none of the following.\n        cisco - cisco proprietary H.323 Lite session protocol.\n        sdp   - Session Description Protocol.\n        sip   - Session Initiation Protocol.\n        sccp  - Skinny Call Control Protocol.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4, 5, 6))
    namedValues = NamedValues(("other", 1), ("cisco", 2), ("sdp", 3), ("sip", 4), ("multicast", 5), ("sccp", 6))

class CvCasGroup(TextualConvention, Integer32):
    description = 'The Channel Associated Signalling Group of a\n        T1/E1. The valid CAS group range is from 0 to 23 for T1\n        and from 0 to 30 for E1. The value -1 indicates CAS group is\n        disabled.'
    status = 'current'
    displayHint = 'd'
    subtypeSpec = Integer32.subtypeSpec + ValueRangeConstraint(-1, 30)

class CvAmrNbBitRateMode(TextualConvention, Bits):
    description = 'Represents GSM AMR-NB bit rate modes.\n\n        CodecMode             Bit-rate (kbps)\n        0                     4.75\n        1                     5.15\n        2                     5.90\n        3                     6.70\n        4                     7.40\n        5                     7.95\n        6                     10.2\n        7                     12.2'
    status = 'current'
    namedValues = NamedValues(("amrBitRateMode0", 0), ("amrBitRateMode1", 1), ("amrBitRateMode2", 2), ("amrBitRateMode3", 3), ("amrBitRateMode4", 4), ("amrBitRateMode5", 5), ("amrBitRateMode6", 6), ("amrBitRateMode7", 7))

class CvAmrNbRtpEncap(TextualConvention, Integer32):
    description = 'Represents GSM AMR-NB codec RTP encapsulation type.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1))
    namedValues = NamedValues(("rfc3267", 1))

class CvIlbcFrameMode(TextualConvention, Integer32):
    reference = 'RFC 3952: Section 4.2 for details about iLBC mode'
    description = 'This Texatual Convention represents the iLBC codec\n        frame modes.  \n        The possible values are :\n        frameMode20: This mode operates at 15.2 kbps and each \n                     frame is packetized in 38 bytes. \n        frameMode30: This mode operates at 13.33 kbps and each \n                     frame is packetized in 50 bytes.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(20, 30))
    namedValues = NamedValues(("frameMode20", 20), ("frameMode30", 30))

class CvCallConnectionType(TextualConvention, Integer32):
    description = 'Call connection represents the connection/association/session\n        between two media call end points. Following are the different\n        connection types.\n\n        h323       - h323 protocol.\n        sip        - Session Initiation Protocol.\n        mgcp       - Media Gateway Control Protocol.\n        sccp       - Cisco proprietary Skinny Call Control Protocol.\n        multicast  - multicast call connections.\n        cacontrol  - Call Agent Control.\n        telephony  - telephony signal call connections.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4, 5, 6, 7))
    namedValues = NamedValues(("h323", 1), ("sip", 2), ("mgcp", 3), ("sccp", 4), ("multicast", 5), ("cacontrol", 6), ("telephony", 7))

cvdcMIBObjects = MibIdentifier((1, 3, 6, 1, 4, 1, 9, 9, 63, 1))
cvGeneralConfiguration = MibIdentifier((1, 3, 6, 1, 4, 1, 9, 9, 63, 1, 1))
cvPeer = MibIdentifier((1, 3, 6, 1, 4, 1, 9, 9, 63, 1, 2))
cvGatewayCallActive = MibIdentifier((1, 3, 6, 1, 4, 1, 9, 9, 63, 1, 3))
cvGatewayCallHistory = MibIdentifier((1, 3, 6, 1, 4, 1, 9, 9, 63, 1, 4))
cvGeneralPoorQoVNotificationEnable = MibScalar((1, 3, 6, 1, 4, 1, 9, 9, 63, 1, 1, 1), TruthValue().clone('false')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: cvGeneralPoorQoVNotificationEnable.setStatus('current')
if mibBuilder.loadTexts: cvGeneralPoorQoVNotificationEnable.setDescription("This object indicates whether cvdcPoorQoVNotification (or\n        the newer cvdcPoorQoVNotificationRev1) traps should be\n        generated for a poor quality of voice calls.\n\n        If the value of this object is 'true',\n        cvdcPoorQoVNotification (or the newer\n        cvdcPoorQoVNotificationRev1) traps will be generated\n        for all voice over IP peers when a poor quality of voice\n        call condition is detected after the voice gateway call\n        disconnection.  If the value of this object is 'false',\n        cvdcPoorQoVNotification (or the newer\n        cvdcPoorQoVNotificationRev1) traps will be generated only\n        for calls for which the\n        cvVoIPPeerCfgPoorQoVNotificationEnable object of voice\n        over IP peers having set to 'true'.")
cvGeneralFallbackNotificationEnable = MibScalar((1, 3, 6, 1, 4, 1, 9, 9, 63, 1, 1, 2), TruthValue().clone('false')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: cvGeneralFallbackNotificationEnable.setStatus('current')
if mibBuilder.loadTexts: cvGeneralFallbackNotificationEnable.setDescription("This object indicates whether cvdcFallbackNotification\n        traps should be generated for fallback.\n        If the value of this object is 'true',\n        cvdcFallbackNotification traps will be generated\n        for all voice over IP peers.")
cvGeneralDSCPPolicyNotificationEnable = MibScalar((1, 3, 6, 1, 4, 1, 9, 9, 63, 1, 1, 3), TruthValue().clone('false')).setMaxAccess("readwrite")
